// Function Helpers
function sembunyikanLoading() {
  const loader = document.getElementById('loading-awal');
  if (loader) loader.remove();
  const target = document.getElementById('halaman-order');
  if (target) target.classList.add('siap');
}

// ==================== [ 2. FETCH & DEKRIPSI DINAMIS ] ====================
fetch('/api/get-system-code')
  .then(res => {
    if (!res.ok) throw new Error("Akses Ditolak");
    return res.json();
  })
  .then(data => {
    if (!data.payload || !data.k) {
      document.getElementById('halaman-order').innerText = "Gagal memuat halaman penjualan.";
      sembunyikanLoading();
      return;
    }

    // --- PROSES DEKRIPSI XOR DI MEMORI BROWSER ---
    const secretKey = "AmanahKey_" + data.k;
    
    // Decode Base64 Biner
    const binary = atob(data.payload);
    const encryptedBytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) {
      encryptedBytes[i] = binary.charCodeAt(i);
    }

    // XOR Decrypt
    const encoder = new TextEncoder();
    const keyBytes = encoder.encode(secretKey);
    const decryptedBytes = new Uint8Array(encryptedBytes.length);

    for (let i = 0; i < encryptedBytes.length; i++) {
      decryptedBytes[i] = encryptedBytes[i] ^ keyBytes[i % keyBytes.length];
    }

    // Decode UTF-8 HTML
    const decodedHTML = new TextDecoder().decode(decryptedBytes);

    // --- INJEKSI KE DOM ---
    const parser = new DOMParser();
    const docBaru = parser.parseFromString(decodedHTML, 'text/html');

    // 1. Pindahkan aset non-script dari <head>
    Array.from(docBaru.head.children).forEach(el => {
      if (el.tagName !== 'SCRIPT') {
        document.head.appendChild(el.cloneNode(true));
      }
    });

    // 2. Suntikkan isi <body>
    const container = document.getElementById('halaman-order');
    container.innerHTML = docBaru.body.innerHTML;

    // 3. Kumpulkan & Jalankan Script secara Berurutan
    const semuaScriptAsli = [
      ...docBaru.head.querySelectorAll('script'),
      ...docBaru.body.querySelectorAll('script')
    ];

    const janjiScriptSelesai = semuaScriptAsli.map(oldScript => {
      return new Promise((resolve) => {
        const newScript = document.createElement('script');
        
        // Salin attribute
        Array.from(oldScript.attributes).forEach(attr => newScript.setAttribute(attr.name, attr.value));

        if (oldScript.src) {
          newScript.src = oldScript.src;
          newScript.onload = resolve;
          newScript.onerror = resolve;
        } else {
          newScript.textContent = oldScript.textContent;
          resolve();
        }
        document.body.appendChild(newScript);
      });
    });

    const jedaMinimal = new Promise(resolve => setTimeout(resolve, 500));

    // 4. Selesai memuat konten -> Trigger Event & Hilangkan Loader
    Promise.all([...janjiScriptSelesai, jedaMinimal]).then(() => {
      document.dispatchEvent(new Event('DOMContentLoaded', { bubbles: true, cancelable: true }));
      window.dispatchEvent(new Event('load'));

      setTimeout(sembunyikanLoading, 150);
    });
  })
  .catch((err) => {
    console.error("System Error:", err);
    document.getElementById('halaman-order').innerText = "Gangguan koneksi sistem.";
    sembunyikanLoading();
  });


// ==================== [ 3. PROTEKSI DEVTOOLS (FIXED) ] ====================
// Inisialisasi variabel agar tidak error undefined
var devToolsOpen = false;

var devtoolsCheckFunction = function() {
  try {
    var start = performance.now();
    console.profile(); 
    console.profileEnd(); 
    var end = performance.now();
    
    if (end - start > 50) { 
      if (!devToolsOpen) {
        devToolsOpen = true; 
        window.location.href = 'about:blank';
      }
    } else {
      devToolsOpen = false;
    }
  } catch (e) {
    if (!devToolsOpen) {
      devToolsOpen = true; 
      window.location.href = 'about:blank';
    }
  }
  
  setTimeout(devtoolsCheckFunction, 500); 
};

// Jalankan otomatis 2 detik setelah script siap tanpa menunggu window.onload
setTimeout(devtoolsCheckFunction, 2000);
